package com.campusvibe.config;
import com.campusvibe.entity.*; import com.campusvibe.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; import java.time.*;
@Configuration public class DataInitializer { @Bean CommandLineRunner seed(UserRepository u,CategoryRepository c,VenueRepository v,EventRepository e,AnnouncementRepository a,PasswordEncoder p){return args->{if(u.count()>0)return; User admin=user("Festival Admin","admin@campusvibe.com","Admin@123",Role.ADMIN,u,p);User coord=user("Akhil Coordinator","coordinator@campusvibe.com","Coord@123",Role.COORDINATOR,u,p);User judge=user("Anu Judge","judge@campusvibe.com","Judge@123",Role.JUDGE,u,p);User student=user("Demo Student","student@campusvibe.com","Student@123",Role.STUDENT,u,p);student.studentId="CV1001";student.department="CSE";student.year="2";u.saveAll(java.util.List.of(admin,coord,judge,student)); Category tech=c.save(new Category("Technical","Coding and technology events"));Category cult=c.save(new Category("Cultural","Music, dance and stage events"));Venue aud=v.save(new Venue("Main Auditorium","Academic Block",800));Venue lab=v.save(new Venue("Computer Lab","IT Block",120)); Event h=new Event();h.name="Hackathon";h.description="24-hour campus coding challenge.";h.category=tech;h.eventType="TEAM";h.date=LocalDate.now().plusDays(5);h.startTime=LocalTime.of(9,0);h.endTime=LocalTime.of(17,0);h.venue=lab;h.maxParticipants=120;h.registrationDeadline=LocalDateTime.now().plusDays(4);h.coordinator=coord;h.judge=judge;h.status="UPCOMING";e.save(h);Event b=new Event();b.name="Battle of Bands";b.description="Live music competition.";b.category=cult;b.eventType="TEAM";b.date=LocalDate.now().plusDays(7);b.startTime=LocalTime.of(18,0);b.endTime=LocalTime.of(21,0);b.venue=aud;b.maxParticipants=80;b.registrationDeadline=LocalDateTime.now().plusDays(6);b.coordinator=coord;b.judge=judge;b.status="UPCOMING";e.save(b);Announcement x=new Announcement();x.title="CAMPUS VIBE 2026 registrations are open";x.description="Register for your favourite events before the deadline.";x.priority="HIGH";a.save(x);};} private User user(String n,String em,String pw,Role r,UserRepository u,PasswordEncoder p){User x=new User();x.name=n;x.email=em;x.password=p.encode(pw);x.role=r;return x;} }
